	private static EndpointConfiguration configuration(Object scope, boolean references, boolean canonical) {
		EndpointConfiguration configuration = mock(EndpointConfiguration.class);
		when(configuration.getBNodeIdentityScope()).thenReturn(scope);
		when(configuration.supportsBlankNodeReferences()).thenReturn(references);
		when(configuration.supportsCanonicalBNodeIDs()).thenReturn(canonical);
		return configuration;
	}

	private enum Operation {
		ADD,
		REMOVE,
		CLEAR;

		void write(WriteStrategy strategy, Resource subject, Value object, Resource[] contexts) {
			switch (this) {
			case ADD -> strategy.addStatement(subject, PREDICATE, object, contexts);
			case REMOVE -> strategy.removeStatement(subject, PREDICATE, object, contexts);
			case CLEAR -> strategy.clear(contexts);
			}
		}

		void verifyWrite(RepositoryConnection connection, Resource subject, Value object, Resource[] contexts) {
			switch (this) {
			case ADD -> verify(connection).add(subject, PREDICATE, object, contexts);
			case REMOVE -> verify(connection).remove(subject, PREDICATE, object, contexts);
			case CLEAR -> verify(connection).clear(contexts);
			}
		}
	}
